import json

input_data = _items[0]["json"]

open_cases = input_data.get("open_cases", [])

if not isinstance(open_cases, list):
    raise ValueError("open_cases must be an array.")

if len(open_cases) > 1:
    raise ValueError(
        "Multiple open cases found for this support person and chat."
    )

existing_case_id = ""
previous_case_data = {}

if open_cases:
    existing_case = open_cases[0]
    existing_case_id = existing_case["case_id"]

    raw_case = existing_case.get("case_data")

    if not raw_case:
        raise ValueError("The existing case has no saved case_data.")

    try:
        previous_case_data = (
            json.loads(raw_case)
            if isinstance(raw_case, str)
            else raw_case
        )
    except json.JSONDecodeError as exc:
        raise ValueError("Saved case_data contains invalid JSON.") from exc

    if not isinstance(previous_case_data, dict):
        raise ValueError("Saved case_data must be an object.")

# The conversation is passed on its own, not inside the previous case.
transcript = previous_case_data.pop("transcript", [])
if not isinstance(transcript, list):
    transcript = []


def feature_modules(raw):
    """Where a feature lives in code, e.g. Modules/AI or apps/web."""
    try:
        items = json.loads(raw) if isinstance(raw, str) and raw.strip() else (raw or [])
    except json.JSONDecodeError:
        return []
    modules = []
    for item in items if isinstance(items, list) else []:
        parts = [part for part in str((item or {}).get("path", "")).split("/") if part]
        if not parts:
            continue
        module = "/".join(parts[:2]) if len(parts) >= 3 else parts[0]
        if module not in modules:
            modules.append(module)
    return modules[:4]
raw_catalog = input_data.get("feature_catalog_draft")

if not isinstance(raw_catalog, list) or not raw_catalog:
    raise ValueError("No active features were loaded.")


def parse_array(value, field, feature_key):
    if value is None or value == "":
        return []

    if isinstance(value, str):
        try:
            value = json.loads(value)
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Invalid JSON in {feature_key}.{field}"
            ) from exc

    if not isinstance(value, list):
        raise ValueError(
            f"Expected an array in {feature_key}.{field}"
        )

    return value


# evidence, uncertainties and repositories are for catalog review; the intake model does not need them.
array_fields = [
    "required_identifiers",
    "search_terms",
]

feature_catalog = []

for row in raw_catalog:
    if not isinstance(row, dict) or not row.get("feature_key"):
        raise ValueError("A catalog row has no feature_key.")

    feature_key = row["feature_key"]

    feature = {
        "feature_key": feature_key,
        "display_name_fa": row.get("display_name_fa", ""),
        "display_name_en": row.get("display_name_en", ""),
        "description": row.get("description", ""),
    }

    for field in array_fields:
        feature[field] = parse_array(
            row.get(field), field, feature_key
        )

    raw_rules = row.get("intake_rules")

    if raw_rules is None or raw_rules == "":
        intake_rules = {"version": 1, "rules": []}
    else:
        try:
            intake_rules = (
                json.loads(raw_rules)
                if isinstance(raw_rules, str)
                else raw_rules
            )
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Invalid JSON in {feature_key}.intake_rules"
            ) from exc

        if not isinstance(intake_rules, dict):
            raise ValueError(
                f"{feature_key}.intake_rules must be an object."
            )

        if intake_rules.get("version") != 1:
            raise ValueError(
                f"Unsupported intake_rules version for {feature_key}."
            )

        rules = intake_rules.get("rules")
        if not isinstance(rules, list):
            raise ValueError(
                f"{feature_key}.intake_rules.rules must be an array."
            )

        if not all(isinstance(rule, dict) for rule in rules):
            raise ValueError(
                f"Each intake rule for {feature_key} must be an object."
            )

    feature["intake_rules"] = intake_rules

    feature["modules"] = feature_modules(row.get("evidence"))
    feature_catalog.append(feature)

message = input_data.get("telegram_message")

if not isinstance(message, dict):
    raise ValueError("Missing Telegram message.")

chat_id = (message.get("chat") or {}).get("id")
support_user_id = (message.get("from") or {}).get("id")

if chat_id is None or support_user_id is None:
    raise ValueError("Missing Telegram chat or sender information.")

photos = [
    photo for photo in (message.get("photos") or [])
    if isinstance(photo, dict) and photo.get("file_id")
]

return [{
    "json": {
        "chat_id": str(chat_id),
        "support_user_id": str(support_user_id),
        "message_id": message.get("message_id"),
        "message_text": (
            message.get("text") or message.get("caption") or ""
        ),
        "has_photo": bool(photos),
        "photo_count": len(photos),
        "photo_files": [
            photo for photo in photos if (photo.get("file_size") or 0) <= 3_500_000
        ],
        "feature_catalog_draft": feature_catalog,
        "case_id": existing_case_id,
        "previous_case_data": previous_case_data,
        "transcript": transcript[-20:],
    }
}]

# Rules are supplied by the catalog, never inferred from feature names.
QUESTION_LABELS = {
    "description": "لطفاً مشکل را کوتاه توضیح دهید.",
    "actual_behavior": "هنگام انجام کار دقیقاً چه اتفاقی افتاد؟",
    "expected_behavior": "انتظار داشتید چه نتیجه‌ای ببینید؟",
    "affected_user_id": "شناسه مشتری مربوط به این مشکل چیست؟",
    "user_id": "شناسه مشتری مربوط به این مشکل چیست؟",
    "occurred_at": "مشکل تقریباً چه زمانی رخ داد؟",
    "error_messages": "متن دقیق خطای نمایش‌داده‌شده چیست؟",
    "steps_to_reproduce": "چه مراحلی را انجام دادید تا مشکل رخ داد؟",
    "environment": "مشکل در کدام محیط رخ داد؟",
    "entity": "کدام موضوع یا جنبه برای تحلیل انتخاب شده بود؟",
    "request_id": "شناسه درخواست موجود چیست؟",
}
NOTE_PREFIX = "اعتبارسنجی ورودی: "


def present(value):
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return any(present(entry) for entry in value)
    return value is not None and value != {}


def string_list(value, label):
    if not isinstance(value, list) or any(
        not isinstance(entry, str) or not entry.strip() for entry in value
    ):
        raise ValueError(f"{label} must be an array of nonempty strings.")
    return list(dict.fromkeys(value))


def add_note(output, text):
    note = NOTE_PREFIX + text
    if note not in output["review_notes"]:
        output["review_notes"].append(note)


for item in _items:
    data = item["json"]
    output = data.get("output")
    catalog = data.get("feature_catalog_draft")

    if not isinstance(output, dict) or not isinstance(output.get("case"), dict):
        raise ValueError("Missing structured intake output.")
    if not isinstance(catalog, list) or not catalog:
        raise ValueError("Missing feature catalog for validation.")

    case = output["case"]
    output["ready_for_investigation"] = False
    output["review_notes"] = [
        note for note in output.get("review_notes", [])
        if isinstance(note, str) and not note.startswith(NOTE_PREFIX)
    ]
    validation = {
        "rule_version": None,
        "rule_matched": False,
        "status": "MANUAL_REVIEW",
        "missing_fields": [],
    }
    data["validation"] = validation

    keys = [feature.get("feature_key") for feature in catalog]
    if any(not isinstance(key, str) or not key for key in keys):
        raise ValueError("Catalog contains an invalid feature key.")
    if len(keys) != len(set(keys)):
        raise ValueError("Catalog contains duplicate feature keys.")

    feature = next(
        (entry for entry in catalog if entry["feature_key"] == case.get("feature_key")),
        None,
    )
    if feature is None:
        case["feature_key"] = ""
        case["feature_name"] = ""
        output["status"] = "UNKNOWN_FEATURE"
        output["missing_fields"] = ["feature_key"]
        validation["status"] = "UNKNOWN_FEATURE"
        validation["missing_fields"] = ["feature_key"]
        add_note(output, "ویژگی گزارش با فهرست فعلی تطبیق داده نشد.")
        output["questions"] = output.get("questions", [])[:3]
        output["reply_text"] = (
            "این گزارش هنوز با ویژگی‌های فهرست فعلی تطبیق داده نشده و نیاز به بررسی دارد."
            + ("\n" + "\n".join(output["questions"]) if output["questions"] else "")
        )
        continue

    config = feature.get("intake_rules")
    if (
        not isinstance(config, dict)
        or not isinstance(config.get("version"), int)
        or isinstance(config.get("version"), bool)
        or config["version"] != 1
        or not isinstance(config.get("rules"), list)
    ):
        raise ValueError("Invalid or unparsed catalog intake_rules.")

    validation["rule_version"] = config["version"]
    matches = []
    selectors = set()
    for rule in config["rules"]:
        if not isinstance(rule, dict):
            raise ValueError("Each intake rule must be an object.")
        selector = (rule.get("scenario"), rule.get("request_state"))
        if any(not isinstance(value, str) or not value for value in selector):
            raise ValueError("Each rule needs scenario and request_state.")
        if selector in selectors:
            raise ValueError("Duplicate scenario/request_state intake rules.")
        selectors.add(selector)
        if selector == (case.get("scenario"), case.get("request_state")):
            matches.append(rule)

    if not matches:
        add_note(output, "برای این سناریو هنوز قاعده جمع‌آوری اطلاعات تعریف نشده؛ بررسی دستی لازم است.")
        if output.get("questions"):
            output["status"] = "NEED_MORE_INFO"
            output["questions"] = output["questions"][:3]
            output["reply_text"] = (
                "برای ادامه بررسی، لطفاً این موارد را توضیح دهید:\n"
                + "\n".join(output["questions"])
            )
        else:
            output["status"] = "READY_FOR_REVIEW"
            output["questions"] = []
            output["reply_text"] = "اطلاعات گزارش دریافت شد؛ کامل‌بودن آن باید به‌صورت دستی بررسی شود."
        validation["missing_fields"] = output.get("missing_fields", [])
        continue

    rule = matches[0]
    validation["rule_matched"] = True
    required_fields = string_list(rule.get("required_case_fields"), "required_case_fields")
    required_ids = string_list(rule.get("required_identifiers"), "required_identifiers")
    impossible_ids = string_list(rule.get("unavailable_identifiers"), "unavailable_identifiers")
    definitions = feature.get("required_identifiers", [])
    allowed_ids = {entry["name"] for entry in definitions}

    if any(field not in case for field in required_fields):
        raise ValueError("An intake rule references an unknown case field.")
    if not set(required_ids + impossible_ids).issubset(allowed_ids):
        raise ValueError("An intake rule references an unknown catalog identifier.")
    if set(required_ids) & set(impossible_ids):
        raise ValueError("An intake rule both requires and excludes an identifier.")

    identifiers = {}
    conflicts = []
    for entry in case.get("collected_identifiers", []):
        name = entry["name"]
        value = entry["value"].strip()
        if not value:
            continue
        if name not in allowed_ids:
            conflicts.append(name)
        if name in identifiers and identifiers[name] != value:
            conflicts.append(name)
        identifiers[name] = value

    unavailable = string_list(case.get("unavailable_fields", []), "unavailable_fields")
    for name in impossible_ids:
        if name in identifiers:
            conflicts.append(name)
        elif name not in unavailable:
            unavailable.append(name)

    if (
        present(case.get("affected_user_id"))
        and "user_id" in identifiers
        and case["affected_user_id"].strip() != identifiers["user_id"]
    ):
        conflicts.append("user_id")

    # Explicitly supplied values supersede an earlier unavailable marker.
    unavailable = [
        name for name in unavailable
        if name in impossible_ids
        or not present(identifiers.get(name, case.get(name)))
    ]
    case["unavailable_fields"] = unavailable

    missing = list(dict.fromkeys(
        [name for name in required_fields if not present(case.get(name))]
        + [name for name in required_ids if not present(identifiers.get(name))]
    ))
    output["missing_fields"] = missing
    validation["missing_fields"] = missing

    # Optional catalog questions let new identifiers work without code changes.
    custom_questions = rule.get("questions", {})
    if not isinstance(custom_questions, dict) or any(
        name not in required_fields + required_ids
        or not isinstance(question, str) or not question.strip()
        for name, question in custom_questions.items()
    ):
        raise ValueError("Rule questions must map required field names to question text.")

    questions = []
    for name in missing:
        if name in unavailable:
            continue
        question = custom_questions.get(name) or QUESTION_LABELS.get(name)
        if question and question not in questions:
            questions.append(question)
    output["questions"] = questions[:3]

    if conflicts:
        validation["status"] = "MANUAL_REVIEW"
        add_note(output, "شناسه‌های ناسازگار یا نامعتبر نیاز به بررسی دستی دارند: " + ", ".join(sorted(set(conflicts))))
    elif missing:
        validation["status"] = "NEEDS_INFORMATION" if questions else "MANUAL_REVIEW"
    else:
        validation["status"] = "INTAKE_COMPLETE"

    if missing:
        add_note(output, "اطلاعات الزامی حل‌نشده: " + ", ".join(missing))
    if questions:
        output["status"] = "NEED_MORE_INFO"
        output["reply_text"] = (
            "برای تکمیل گزارش، لطفاً به این پرسش‌ها پاسخ دهید:\n"
            + "\n".join(f"{index + 1}) {question}" for index, question in enumerate(output["questions"]))
        )
    else:
        output["status"] = "READY_FOR_REVIEW"
        output["reply_text"] = (
            "اطلاعات گزارش دریافت شد؛ موارد حل‌نشده باید به‌صورت دستی بررسی شوند."
            if missing or conflicts else
            "اطلاعات لازم برای بررسی اولیه گزارش دریافت شد و گزارش برای بررسی آماده است."
        )

return _items

