const intake = $('Prepare Intake Input').first().json;
// Failed downloads or descriptions arrive with an error instead of text.
const descriptions = $input.all().map((item, index) => {
  const text = typeof item.json.text === 'string' ? item.json.text.trim() : '';
  return `Photo ${index + 1}: ${text || '(could not be analyzed)'}`;
});
const tooLarge = intake.photo_count - intake.photo_files.length;
if (tooLarge > 0) descriptions.push(`${tooLarge} more photo(s) were too large to analyze.`);
return [{ json: { ...intake, photo_description: descriptions.join('\n\n') } }];

const rows = $input.all()
  .map(item => item.json)
  .filter(row => row.id)
  .sort((a, b) => a.id - b.id);
if (rows.length === 0) return [];  // already processed by /done or a newer run

// After the quiet time, only the run for the newest message processes the batch.
const saved = $('Save To Buffer');
if (saved.isExecuted && rows[rows.length - 1].id !== saved.first().json.id) return [];

const messages = rows.map(row => JSON.parse(row.message_json));
const last = messages[messages.length - 1];
const photos = [];
for (const message of messages) {
  if (Array.isArray(message.photo) && message.photo.length) {
    photos.push(message.photo[message.photo.length - 1]);  // largest size is last
  } else if (String(message.document?.mime_type || '').startsWith('image/')) {
    photos.push(message.document);
  }
}

return [{ json: {
  buffer_max_id: rows[rows.length - 1].id,
  message: {
    message_id: last.message_id,
    chat: last.chat,
    from: last.from,
    date: last.date,
    text: messages.map(m => (m.text || m.caption || '').trim()).filter(Boolean).join('\n'),
    photos: photos.map(p => ({ file_id: p.file_id, file_size: p.file_size || 0 })),
  },
} }];

