const intake = $('Prepare Intake Input').first().json;
const item = JSON.parse(JSON.stringify($('Case Before Reply').first().json));
const output = item.output;
const composed = $input.first().json.text;
// Compose failures fall back to the validation template.
const reply = (typeof composed === 'string' && composed.trim())
  || output.reply_text + (output.status === 'READY_FOR_REVIEW' ? '\n\nبرای ثبت گزارش جدید /new را بفرستید.' : '');
output.reply_text = reply;

const now = new Date().toISOString();
const said = [intake.message_text, intake.photo_count ? `[${intake.photo_count} عکس]` : '']
  .filter(Boolean).join(' ');
output.transcript = [
  ...(intake.transcript || []),
  ...(said ? [{ role: 'support', text: said, at: now }] : []),
  { role: 'bot', text: reply, at: now },
].slice(-20);
return [{ json: item }];

// Most recently seen first; the model compares against at most 30.
const candidates = $input.all()
  .map(item => item.json)
  .filter(row => row.issue_key)
  .sort((a, b) => String(b.last_seen).localeCompare(String(a.last_seen)))
  .slice(0, 30);
return [{ json: { candidates } }];

