const intake = $('Prepare Intake Input').first().json;
const output = $('Apply Triage Rules').first().json.output;
const triage = output.triage || {};
const candidates = $('Collect Candidates').first().json.candidates;
const decision = $input.first().json.output || {};  // empty when the model failed: a new issue is created
const caseId = intake.case_id
  || `case_${intake.chat_id}_${intake.support_user_id}_${intake.message_id}`;
const feature = intake.feature_catalog_draft.find(f => f.feature_key === output.case.feature_key) || {};
const levels = ['low', 'medium', 'high', 'critical'];
const higher = (a, b) => (levels.indexOf(a) >= levels.indexOf(b) ? a : b);
const now = new Date().toISOString();

const matched = candidates.find(c => c.issue_key === decision.match_issue_key);
const isRepeat = Boolean(matched) && (decision.confidence || 0) >= 0.7;
let row;
if (isRepeat) {
  let ids = [];
  try { ids = JSON.parse(matched.case_ids || '[]'); } catch (e) { ids = []; }
  if (!ids.includes(caseId)) ids.push(caseId);
  row = {
    ...matched,
    case_ids: JSON.stringify(ids),
    case_count: ids.length,
    priority: higher(matched.priority || 'medium', triage.priority || 'medium'),
    last_seen: now,
    status: 'open',
  };
} else {
  const stamp = now.slice(2, 10).replace(/-/g, '');
  row = {
    issue_key: `ISS-${stamp}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
    title: decision.title || (output.case.description || '').slice(0, 80),
    feature_key: output.case.feature_key,
    feature_name: output.case.feature_name,
    modules: (feature.modules || []).join(', '),
    team: triage.team || '',
    scenario: output.case.scenario,
    priority: triage.priority || 'medium',
    signature: decision.signature || '',
    case_count: 1,
    case_ids: JSON.stringify([caseId]),
    first_seen: now,
    last_seen: now,
    status: 'open',
  };
}
return [{ json: { row, is_new: !isRepeat, match_reason: decision.reason || '' } }];

const data = JSON.parse(JSON.stringify($('Apply Triage Rules').first().json));
const link = $('Link Issue');
if (link.isExecuted) {
  const { row, is_new } = link.first().json;
  data.output.issue = { issue_key: row.issue_key, title: row.title, count: row.case_count, is_new };
} else {
  // Already linked earlier in this case: keep the link, do not count again.
  data.output.issue = $('Prepare Intake Input').first().json.previous_case_data.issue;
}
return [{ json: data }];

const issues = $input.all().map(item => item.json).filter(row => row.issue_key);
if (issues.length === 0) return [{ json: { text: 'هنوز هیچ مشکلی ثبت نشده.' } }];

const TEAM = { backend: 'بک‌اند', frontend: 'فرانت‌اند', devops: 'دواپس' };
const SCENARIO = {
  creation_failed: 'ثبت درخواست ناموفق', result_missing: 'نتیجه نیامده', incorrect_result: 'نتیجه نادرست',
  visibility_problem: 'مشکل دسترسی/نمایش', retry_problem: 'مشکل تلاش دوباره', other: 'سایر', unknown: 'نامشخص',
};
const count = issue => Number(issue.case_count) || 0;
const total = issues.reduce((sum, issue) => sum + count(issue), 0);
const groupBy = (field, label = value => value) => {
  const totals = new Map();
  for (const issue of issues) {
    const keys = String(issue[field] || 'نامشخص').split(', ').filter(Boolean);
    for (const key of keys) totals.set(label(key), (totals.get(label(key)) || 0) + count(issue));
  }
  return [...totals].sort((a, b) => b[1] - a[1]);
};
const list = (rows, limit = 8) => rows.slice(0, limit).map(([name, n]) => `• ${name}: ${n}`);
const weekAgo = Date.now() - 7 * 24 * 3600 * 1000;
const newThisWeek = issues.filter(issue => new Date(issue.first_seen).getTime() >= weekAgo);
const top = [...issues].sort((a, b) => count(b) - count(a)).slice(0, 5);

const lines = [
  '📊 گزارش مشکلات دیتامی',
  `${issues.length} مشکل جدا، در مجموع ${total} گزارش`,
  '', 'بر اساس تیم:', ...list(groupBy('team', t => TEAM[t] || t)),
  '', 'بر اساس بخش کد (ماژول):', ...list(groupBy('modules')),
  '', 'بر اساس قابلیت:', ...list(groupBy('feature_name')),
  '', 'بر اساس نوع مشکل:', ...list(groupBy('scenario', s => SCENARIO[s] || s)),
  '', 'پرتکرارترین مشکل‌ها:', ...top.map(i => `• ${i.title} — ${count(i)} بار (${i.issue_key})`),
  '', `مشکل‌های جدید ۷ روز اخیر: ${newThisWeek.length}`,
];
return [{ json: { text: lines.join('\n').slice(0, 4000) } }];
